// Watch Face Format faces are resource-only APKs: no code, just
// res/raw/watchface.xml (generated by gen/face.mjs) and its assets.
plugins {
    alias(libs.plugins.android.application)
}

android {
    enableKotlin = false
    namespace = "ai.howie.solarclock"
    compileSdk = 36

    defaultConfig {
        applicationId = "ai.howie.solarclock"
        // WFF v4 (Reference, used to carry longitude) needs Wear OS 6 / API 36.
        minSdk = 36
        targetSdk = 36
        versionCode = 1
        versionName = "0.1.0"
    }

    buildTypes {
        debug {
            isMinifyEnabled = true
        }
        release {
            isMinifyEnabled = true
            isShrinkResources = false
            signingConfig = signingConfigs.getByName("debug")
        }
    }
}
